for(const r of BERT_DATA.reference.norms){for(const [key,rms] of [['ln',false],['rms',true]])Transformer.norm(r.x,rms).forEach((v,i)=>{if(Math.abs(v-r[key][i])>1e-9)throw Error(key);});}
for(const r of BERT_DATA.reference.rope){const q=Transformer.rotate([1,0,.5,-1],r.p),k=Transformer.rotate([.5,1,-1,.5],r.r);for(const [key,a]of [['q',q],['k',k]])a.forEach((v,i)=>{if(Math.abs(v-r[key][i])>1e-9)throw Error('rotate');});if(Math.abs(Transformer.dot(q,k)-r.score)>1e-9)throw Error('score');}
const g=BERT_DATA.reference.gate;for(const name of ['silu','gelu'])g.x.forEach((v,i)=>{if(Math.abs(Transformer[name](v)-g[name][i])>1e-9)throw Error(name);});for(const r of BERT_DATA.reference.ffn){const a=BERT.ffnValues(r.kind,r.coordinate,r.raw);for(const [key,actual] of [['hidden',a.h],['output',a.out]])actual.forEach((v,i)=>{if(Math.abs(v-r[key][i])>1e-9)throw Error('FFN '+key);});}return BERT_DATA.reference.engine+'; 24 gated FFN cases';

const set=(id,v)=>{const e=document.getElementById(id);e.value=v;e.dispatchEvent(new Event('input',{bubbles:true}));};
for(let i=0;i<7;i++){set('bert-token',i);if(BERT.token!==i)throw Error('token');}document.querySelector('[data-token="2"]').dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',bubbles:true}));if(BERT.token!==2)throw Error('keyboard');
for(const i of [1,4,6])document.querySelector('[data-mlm="'+i+'"]').dispatchEvent(new MouseEvent('click',{bubbles:true}));document.getElementById('mlm-check').click();if(!document.getElementById('mlm-result').textContent.startsWith('Верно'))throw Error('mlm');document.getElementById('mlm-reset').click();if(BERT.selected.size||BERT.checked)throw Error('reset');
for(let i=0;i<3;i++){set('mlm-example',i);if(!document.getElementById('mlm-predictions').textContent.includes(BERT_DATA.mlm[i].top[0][0]))throw Error('prediction');}return 'token paths, keyboard, three MLM targets and three saved distributions';

const set=(id,v)=>{const e=document.getElementById(id);e.value=v;e.dispatchEvent(new Event('input',{bubbles:true}));};
for(const task of ['seq','ner','qa'])for(const train of ['head','all']){set('head-task',task);set('head-train',train);const s=document.querySelector('[data-fig=heads]').textContent;if(task==='qa'&&!s.includes('start'))throw Error('span');if(task==='ner'&&!s.includes('B-PER'))throw Error('NER');}
set('pretrain-model','roberta');const before=document.querySelector('[data-fig=evolution]').textContent;document.getElementById('mask-next').click();if(before===document.querySelector('[data-fig=evolution]').textContent)throw Error('dynamic mask');set('pretrain-model','electra');if(!document.querySelector('[data-fig=evolution]').textContent.includes('совпали'))throw Error('ELECTRA');return 'six task/training states, dynamic masks and correct ELECTRA labels';

for(const r of BERT_DATA.reference.masks)r.allowed.forEach((row,i)=>row.forEach((v,j)=>{if(BERT.allowed(r.layer,i,j)!==v)throw Error('mask vs torch');}));const set=(id,v)=>{const e=document.getElementById(id);e.value=v;e.dispatchEvent(new Event('input',{bubbles:true}));};
for(const mode of ['bert','modern'])for(let depth=1;depth<=6;depth++)for(let token=0;token<9;token++){const actual=BERT.reachable(depth,token,mode);if(actual.size!==9)throw Error('global first layer');if(BERT.global(depth,mode)!==(mode==='bert'||[1,4].includes(depth)))throw Error('global');}
set('modern-layer',2);document.querySelector('[data-modern="0"]').dispatchEvent(new MouseEvent('click',{bubbles:true}));if(BERT.modernToken!==0)throw Error('select');const c=document.getElementById('padding-off');for(const flag of [true,false]){c.checked=flag;c.dispatchEvent(new Event('input'));if(!document.getElementById('padding-result').textContent.startsWith(flag?'11':'15'))throw Error('padding');}return 'layer schedule, reachable paths and document boundaries';
